// TH16 v1.00a st02.ecl MainSub01:912-928 道中波。
// 两个 GirlC01 固定炮台（t=0 / t=300 各一对，%F0 抖角不同）＋ t=120 起的左右镜像
// GirlA01 编队（MainSub01b/c:930-960，每侧 5 对红/蓝，间隔 30 帧）。
// 源帧以 MainSub01 第一帧为 0；卡帧再前置 OPENING_BUFFER。

const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;

// TH16 type 8 / 12（已核复用槽，见 touhou-bullets.ecl）。
const TH16_RICE: int = 480;
const TH16_ARROWHEAD: int = 544;

// GirlC01_at:358-410 的 EX 链：ANIM(a=1) 只贡献出生退位移（改由 sh_dist 表达），
// 随后 ACCEL a=230、r=0.013、s=+90°（TH16 字面向量分支）。
xformdef C01_DRIFT {
    @230 set_gravity(0fx, 0.013fx);
    set_gravity(0fx, 0fx);
}

// GirlC01_at:358-410。base=%ANGLE_PLAYER 在 wait(60) 后只取一次；每轮 D 重置 speed。
sub c01_attack(f0: angle) {
    wait(60);
    var step: fx = 0.2fx;          // %B
    var base: angle = aim_player(); // %C = %ANGLE_PLAYER
    var shots: int = 3;             // diffI($E, 3, 3, 5, 7)
    var gap: int = 10;
    var tail: int = 120;
    if global(GVAR_RANK) == RANK_HARD {
        shots = 5;
        gap = 5;
        tail = 10;
    }
    if global(GVAR_RANK) >= RANK_LUNATIC {
        shots = 7;
        gap = 3;
        tail = 10;
    }
    sh_reset(0);
    sh_sprite(0, TH16_ARROWHEAD, 13);  // etSprite(0, 12, 13)
    sh_ring(0, 1);                     // etAim(0, 3) 固定方向环
    sh_aim(0, 0);
    sh_count(0, 5, 1);                 // etCount(0, 5, 1)
    sh_xform(0, C01_DRIFT);
    for round in 0..3 {                // $D = 3，先判后跑
        var speed: fx = 1fx;           // %A = 1.0f 每轮重置
        for k in 0..shots {
            sh_speed(0, speed, 0fx);   // etSpeed(0, %A, 0.0f)
            sh_dist(0, -4fx * speed);  // ANIM a=1：position -= 4*velocity
            sh_angle(0, base, 0deg);   // etAngle(0, %C, 0.0f)
            sh_fire(0);
            speed = speed + step;      // %A += %B
            base = base + f0;          // %C += %F0
            wait(gap);
        }
        wait(tail);
    }
}

// GirlC01:337-356。下落 60 帧减速到 0.01，发弹，再加速上飞 700 帧后 delete()。
async sub c01(f0: angle) {
    set_invuln(65535);
    set_hurtbox(16fx);                 // setHurtbox(32,32)
    set_hitbox(12fx);                  // setHitbox(24,24)
    move_vel(0, 90deg, 2fx, EASE_LINEAR);
    move_vel(60, 90deg, 0.01fx, EASE_QUAD_IN);   // mode1
    c01_attack(f0);
    move_vel(0, -90deg, 0fx, EASE_LINEAR);
    wait(90);
    move_vel(70, -90deg, 4fx, EASE_QUAD_IN);     // mode1
    wait(700);
}

// GirlA01_at:24-70（GirlBlue/RedA01e 仅在 !NHL 挂 async）。
async sub girl_shot() {
    var ways: int = 1;                 // etCount(0, [-1], 1)：E/N/H = 1，LO = 3
    var speed: fx = 2fx;               // E/N = 2.0，H/LO = 3.0
    var volleys: int = 3;              // diffI($A, 3, 3, 8, 12)
    var gap_base: int = 40;
    var gap_span: int = 140;           // E/N = 40 + RAND%140
    if global(GVAR_RANK) == RANK_HARD {
        speed = 3fx;
        volleys = 8;
        gap_base = 30;
        gap_span = 20;                 // H = 30 + RAND%20
    }
    if global(GVAR_RANK) >= RANK_LUNATIC {
        ways = 3;
        speed = 3fx;
        volleys = 12;
        gap_base = 20;
        gap_span = 20;                 // LO = 20 + RAND%20
    }
    sh_reset(0);
    sh_sprite(0, TH16_RICE, 2);        // etSprite(0, 8, 2)
    sh_ring(0, 0);                     // etAim(0, 1) 固定方向扇形
    sh_aim(0, 0);
    sh_count(0, ways, 1);
    sh_speed(0, speed, 0fx);           // etSpeed(0, [-1.0f], 1.0f)：单层只用首速
    sh_dist(0, -4fx * speed);          // ANIM a=1 出生退位移
    var base: angle = 90deg + ((rand(3641) - 1820) as angle);  // %RANDF2 * 10°
    sh_angle(0, base, 40deg);          // etAngle(0, 90°+rand, 0.6981317)
    for i in 0..volleys {
        wait(gap_base + rand(gap_span));
        sh_fire(0);
    }
}

// GirlA01:6-22 的移动；mirror=1 时角度按 x 轴反射（424/enmCreateM 的镜像）。
async sub girl_a01(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);                 // setHurtbox(24,24)
    set_hitbox(8fx);                   // setHitbox(16,16)
    var a0: angle = 67.5deg;           // 1.1780972f
    var a1: angle = 22.5deg;           // 0.3926991f
    var a2: angle = -11.25deg;         // -0.19634955f
    if mirror == 1 {
        a0 = 180deg - a0;
        a1 = 180deg - a1;
        a2 = 180deg - a2;
    }
    if global(GVAR_RANK) != RANK_EASY {
        spawn girl_shot();             // @GirlA01_at() async
    }
    move_vel(0, a0, 2fx, EASE_LINEAR);
    wait(30);
    move_vel(60, a1, 1fx, EASE_LINEAR);   // mode0
    wait(60);
    move_vel(60, a2, 2fx, EASE_LINEAR);   // mode0
    loop { wait(1000); }               // GirlA01_284：源里不主动退场
}

// MainSub01b:930-944 / MainSub01c:946-960。两侧各 5 对，红蓝间隔 30 帧；
// 红蓝除表现/掉落外行为相同（Girl*e 均先挂 GirlA01_at 再跑 GirlA01）。
async sub girl_side(x: fx, mirror: int) {
    for i in 0..5 {
        _ = spawn_enemy(x, -16fx, 100, 0, 1000, 0, girl_a01(mirror));
        wait(30);
        _ = spawn_enemy(x, -16fx, 100, 0, 1000, 0, girl_a01(mirror));
        wait(30);
    }
}

// MainSub01:912-928 主体（相对卡帧 120 起）。
async sub wave() {
    wait(OPENING_BUFFER);
    // %F0 = +2° / -2°
    _ = spawn_enemy(128fx, -24fx, 700, 0, 1000, 0, c01(2deg));
    _ = spawn_enemy(-128fx, -24fx, 700, 0, 1000, 0, c01(-2deg));
    wait(120);
    spawn girl_side(192fx, 1);         // MainSub01b：enmCreateM，镜像侧
    spawn girl_side(-192fx, 0);        // MainSub01c：enmCreate
    wait(180);
    // %F0 = -5° / +5°
    _ = spawn_enemy(128fx, -24fx, 700, 0, 1000, 0, c01(-5deg));
    _ = spawn_enemy(-128fx, -24fx, 700, 0, 1000, 0, c01(5deg));
    wait(60);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 1000, 0, control);
    loop { wait(600); }
}
